import{_ as a,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const h=JSON.parse('{"title":"Reativar localizadores pelo histórico","description":"","frontmatter":{"title":"Reativar localizadores pelo histórico","id":"eproc-reativar-localizador-historico","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.8.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-reativar-localizador-historico"}]]},"headers":[],"relativePath":"funcionalidades/eproc-reativar-localizador-historico.md","filePath":"funcionalidades/eproc-reativar-localizador-historico.md"}'),i={name:"funcionalidades/eproc-reativar-localizador-historico.md"};function l(c,o,t,d,n,p){return e(),r("div",null,o[0]||(o[0]=[s('<h1 id="reativar-localizadores-pelo-historico" tabindex="-1">Reativar localizadores pelo histórico <a class="header-anchor" href="#reativar-localizadores-pelo-historico" aria-label="Permalink to &quot;Reativar localizadores pelo histórico&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No histórico de localizadores do processo, os localizadores já excluídos aparecem riscados, sem forma de devolvê-los ao processo. Este recurso permite selecionar esses localizadores e reativá-los: o editor de localizadores da capa abre com eles já incluídos, para você conferir e salvar.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, &quot;Histórico de Localizadores do Processo&quot;, aberto a partir da capa do processo.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Na capa do processo, abra o histórico de localizadores.</li><li>Clique nos localizadores excluídos (riscados) que quer devolver. Eles ficam marcados, e uma barra aparece com o botão <strong>Reativar</strong>. Você também pode clicar com o botão direito num localizador e escolher &quot;Reativar&quot;.</li><li>Clique em <strong>Reativar</strong>. O histórico se fecha e o editor de localizadores da capa abre com os selecionados incluídos como localizadores <strong>secundários</strong>.</li><li>Confira e salve no editor. Nada é gravado antes disso.</li></ol><p>Para desfazer a seleção antes de reativar, use o botão &quot;Limpar seleção&quot; da barra.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Localizadores excluídos que já estão ativos de novo não são clicáveis. Ao passar o mouse sobre eles, o localizador ativo de mesmo nome fica destacado.</li><li>Com &quot;Mostrar localizadores de todos os órgãos&quot; ligado no histórico, a reativação não é oferecida, porque localizadores de outros órgãos não estão disponíveis no editor.</li></ul>',12)]))}const m=a(i,[["render",l]]);export{h as __pageData,m as default};
